#include <iostream>
bool checkedArea(int width, int height, int& result) {
    if (width < 0 || width > 1000 || height < 0 || height > 1000) { return false; }
    result = width * height;
    return true;
}
int main() {
    int result{17};
    bool ok = checkedArea(-1, 2, result);
    std::cout << ok << ' ' << result << '\n';
    ok = checkedArea(3, 4, result);
    std::cout << ok << ' ' << result << '\n';
}

