#include <iostream>
bool checkedArea(int width, int height, int& result) {
    if (width < 0 || width > 1000 || height < 0 || height > 1000) { return false; }
    result = width * height;
    return true;
}
int main() {
    int width{}, height{};
    if (!(std::cin >> width >> height)) { std::cout << "invalid\n"; return 0; }
    std::cin >> std::ws;
    int result{-7};
    if (!std::cin.eof() || !checkedArea(width, height, result)) { std::cout << "invalid\n"; return 0; }
    std::cout << result << '\n';
}
